function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length >= 10000) return 'arr needs 1 to 9999 values.';
  for (let i = 0; i < arr.length; i++) {
    if (!Number.isInteger(arr[i]) || arr[i] < -1e9 || arr[i] > 1e9) return 'Each value is an integer between -10^9 and 10^9.';
    if (i > 0 && arr[i] <= arr[i - 1]) return 'arr must be strictly increasing.';
  }
  return null;
}

reference:
function fixedPoint(arr) {
  let left = 0;
  let right = arr.length - 1;
  let answer = -1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (arr[mid] === mid) {
      answer = mid;
      right = mid - 1;
    } else if (arr[mid] < mid) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return answer;
}

