function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const arr = [];
  // Steps of at least 1 keep the values distinct and increasing; mostly steps of 1 make fixed-point runs likely.
  let value = size === 'large' ? -Math.floor(rand() * 400) : Math.floor(rand() * 9) - 6;
  for (let i = 0; i < n; i++) {
    arr.push(value);
    value += rand() < 0.75 ? 1 : 2 + Math.floor(rand() * 3);
  }
  return [arr];
}
